import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"Versioning","description":"","frontmatter":{},"headers":[],"relativePath":"release/versioning.md","filePath":"release/versioning.md"}'),o={name:"release/versioning.md"};function r(s,e,d,l,h,c){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="versioning" tabindex="-1">Versioning <a class="header-anchor" href="#versioning" aria-label="Permalink to &quot;Versioning&quot;">​</a></h1><h2 id="the-scheme" tabindex="-1">The scheme <a class="header-anchor" href="#the-scheme" aria-label="Permalink to &quot;The scheme&quot;">​</a></h2><p>Version identifiers are <strong>work-package stage names</strong>: <code>WP-14-docs_release</code>, <code>WP-13-build_system</code>, ... This is the project&#39;s SemVer-equivalent: the stage name IS the compatibility contract conversation (each WP is a release train with its own feature set and gates).</p><p>Additionally every build carries:</p><ul><li><strong>Build number</strong> = the commit count (<code>git rev-list --count HEAD</code>) at build time - monotonically increasing, visible in <code>uname -a</code> and the update manifest&#39;s <code>build</code> field.</li><li><strong>Version banner</strong> = <code>git describe --tags</code> (or an explicit <code>OC_RELEASE_VERSION=</code> override) - baked into the kernel banner, uname, the OTA manifest and the ISO.</li></ul><h2 id="what-the-numbers-mean-together" tabindex="-1">What the numbers mean together <a class="header-anchor" href="#what-the-numbers-mean-together" aria-label="Permalink to &quot;What the numbers mean together&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Where</th><th>Example</th><th>Meaning</th></tr></thead><tbody><tr><td><code>uname -a</code></td><td><code>Open Cube OS WP-13-build_system build 259</code></td><td>the running kernel&#39;s stage + build</td></tr><tr><td>update.json</td><td><code>version: WP-13-build_system, build: 259</code></td><td>the published manifest</td></tr><tr><td>Release tag</td><td><code>WP-13-build_system</code></td><td>the git tag the assets were built from</td></tr><tr><td>gh-pages</td><td>the same two numbers in the download page</td><td>the website mirrors the Release</td></tr></tbody></table><p>One release = one tag = one build number = one manifest = one set of SHA256s across local / Release / gh-pages / private mirror.</p><h2 id="compatibility-promises" tabindex="-1">Compatibility promises <a class="header-anchor" href="#compatibility-promises" aria-label="Permalink to &quot;Compatibility promises&quot;">​</a></h2><ul><li>Shell commands are never removed; additions are the norm (baseline moves UP: 176 -&gt; 192 -&gt; ... -&gt; 233).</li><li>L1 numbered interfaces are never renumbered; new groups append.</li><li>The OTA package updates the kernel only; /etc volume contents carry forward.</li></ul><h2 id="choosing-the-next-version" tabindex="-1">Choosing the next version <a class="header-anchor" href="#choosing-the-next-version" aria-label="Permalink to &quot;Choosing the next version&quot;">​</a></h2><p>The next work package&#39;s stage name (decided in the development plan), with <code>build</code> = whatever the commit count is on release day - never hand-picked.</p>',12)])])}const b=t(o,[["render",r]]);export{u as __pageData,b as default};
